{
  "positionId": "P04",
  "interviews": [
    {
      "categoryId": "P04-C1",
      "itemId": "P04-C1-I1",
      "interviewBlueprint": {
        "questionIntent": "하중 조건을 부품의 주요 치수로 연결하는 설계 판단을 검증한다. 감속기 축 설계 계산 경험에서 축 지름을 정한 판단 근거 하나에 초점을 둔다.",
        "questionType": "behavioral",
        "expectedSTAR": {
          "situation": "기계요소설계 수업에서 교재에 주어진 하중 조건으로 감속기 축을 설계한 상황이다.",
          "task": "주어진 하중을 견디면서 베어링과 결합할 수 있는 축 지름을 정해야 했다.",
          "action": "축에 작용하는 하중과 지지 조건을 계산에 반영하고, 계산 결과를 실제 선정 지름의 근거로 설명한다.",
          "result": "선정한 축 지름이 주어진 설계 조건을 충족한다고 판단한 이유가 드러난다. 제작이나 시험 성과는 요구하지 않는다."
        },
        "expectedEvidence": [
          "축 지름을 정할 때 사용한 구체적인 판단 근거",
          "주어진 하중이 축에 전달되는 방식과 지름 산정 사이의 연결",
          "베어링 지지 또는 결합 조건이 선정 지름에 미친 영향"
        ]
      },
      "question": "기계요소설계 수업에서 교재에 주어진 하중 조건으로 축 지름과 베어링을 선정하셨던데요, 축 지름을 정한 판단 근거는 무엇이었어요?",
      "answerTip": "기억나는 한 사례를 차분히 말씀해 주세요.",
      "evaluationRubric": {
        "excellent": {
          "criteria": [
            "축 지름을 정한 근거를 실제 계산이나 선정 내용에 연결해 구체적으로 설명한다.",
            "하중 전달 방식과 베어링 지지 또는 결합 조건이 지름 결정에 미친 영향을 타당하게 설명한다.",
            "선정 지름이 주어진 조건을 충족한다고 판단한 이유가 명확하다."
          ]
        },
        "acceptable": {
          "criteria": [
            "하중이나 강도 계산 등 축 지름을 정한 관련 근거를 제시한다.",
            "계산 결과와 선정 지름의 연결 또는 베어링 조건에 대한 설명이 일부 부족하지만, 주요 판단 방향은 타당하다."
          ]
        },
        "poor": {
          "criteria": [
            "축 지름을 정한 근거를 제시하지 못하거나 교재 값을 따랐다는 설명에 그친다.",
            "하중이나 지지 조건과 무관한 이유를 제시하거나, 해당 조건이 지름에 미치는 영향을 잘못 설명한다."
          ]
        }
      }
    },
    {
      "categoryId": "P04-C1",
      "itemId": "P04-C1-I2",
      "interviewBlueprint": {
        "questionIntent": "기능상 필요한 부위에 한정해 치수 공차를 좁히는 판단을 검증한다. 감속기 축의 양산 도면에서 엄격한 치수 관리가 필요한 부위를 선택하는 데 초점을 둔다.",
        "questionType": "situational",
        "expectedSTAR": {
          "situation": "감속기 축의 3D 모델을 양산 도면으로 옮기며 베어링 결합부와 비접촉 끝단의 치수 공차를 검토하는 상황이다.",
          "task": "부위별 기능 차이에 따라 치수 공차를 좁혀야 할 곳을 선택해야 한다.",
          "action": "베어링 결합 기능에 필요한 부위를 선택하고, 비접촉 끝단과 치수 관리 수준을 달리할 이유를 설명한다.",
          "result": "필요한 끼워맞춤은 확보하면서 기능과 무관한 부위의 과도한 가공 정밀도 요구를 피할 수 있다는 예상 효과가 드러난다."
        },
        "expectedEvidence": [
          "치수 공차를 좁혀 관리할 부위의 구체적인 선택",
          "선택한 부위의 치수 편차가 베어링 결합 기능에 미치는 영향",
          "비접촉 끝단까지 동일하게 공차를 좁힐 필요가 없는 이유"
        ]
      },
      "question": "감속기 축의 3D 모델을 양산 도면으로 옮기는데, 베어링 결합부와 비접촉 끝단이 있거든요. 그럴 때 치수 공차를 좁힐 곳은 어디로 정하시겠어요?",
      "answerTip": "가정된 상황에서 생각한 내용을 말씀해 주세요.",
      "evaluationRubric": {
        "excellent": {
          "criteria": [
            "베어링 결합부의 기능 치수를 공차 관리 대상으로 구체적으로 선택한다.",
            "치수 편차가 끼워맞춤에 미치는 영향을 근거로 선택의 타당성을 설명한다.",
            "비접촉 끝단에는 같은 수준의 좁은 공차가 불필요함을 설명하며 기능 확보와 불필요한 정밀 가공 방지를 연결한다."
          ]
        },
        "acceptable": {
          "criteria": [
            "베어링 결합부를 우선적인 공차 관리 대상으로 선택하고 결합 기능과 관련된 이유를 제시한다.",
            "치수 편차의 영향이나 비접촉 끝단과 관리 수준을 달리할 이유는 구체성이 부족하다."
          ]
        },
        "poor": {
          "criteria": [
            "공차를 좁힐 부위를 선택하지 못하거나 기능과 무관한 부위를 선택한다.",
            "기능 차이에 대한 설명 없이 모든 치수의 공차를 동일하게 좁혀야 한다고 답한다."
          ]
        }
      }
    }
  ]
}

{
  "positionId": "P14",
  "interviews": [
    {
      "categoryId": "P14-C1",
      "itemId": "P14-C1-I1",
      "interviewBlueprint": {
        "questionIntent": "양산 준비를 위한 설비 배치 판단을 검증한다. 직접 작성한 배치안에서 설비 위치를 정한 근거가 공정 흐름과 생산 조건에 부합하는지에 초점을 둔다.",
        "questionType": "behavioral",
        "expectedSTAR": {
          "situation": "신규 차종 도어 트림 조립 라인의 양산을 준비하며 설비 배치안을 작성하던 상황이다.",
          "task": "담당한 배치안 작성 범위에서 조립 작업 흐름과 생산 조건에 맞는 설비 위치를 정해야 했다.",
          "action": "작업 순서, 작업자 이동, 공정별 사이클 타임 중 실제 배치 판단에 사용한 조건을 들어 선택한 위치의 근거를 설명한다.",
          "result": "해당 근거가 작성한 배치안에 어떻게 반영되었는지 설명한다. 실제 생산 성과가 없다면 배치안에서 의도한 효과와 확인된 사실을 구분한다."
        },
        "expectedEvidence": [
          "클립 체결 지그와 초음파 융착기 위치를 정할 때 사용한 구체적인 판단 근거",
          "그 근거와 연결되는 작업 순서, 이동 동선 또는 공정별 사이클 타임의 실제 조건",
          "선택한 위치가 해당 조건에 적합한 이유와 배치안에 반영된 내용"
        ]
      },
      "question": "신규 차종 도어 트림 조립 라인 양산 준비에서 라인 배치안을 작성하셨던데요, 클립 체결 지그와 초음파 융착기 위치는 어떤 근거로 정하셨어요?",
      "answerTip": "직접 맡았던 장면을 떠올려 말씀해 주세요.",
      "evaluationRubric": {
        "excellent": {
          "criteria": [
            "설비 위치를 정한 근거를 본인이 작성한 배치안의 구체적인 내용으로 설명한다.",
            "작업 순서, 이동 동선 또는 사이클 타임의 실제 조건과 선택한 위치 사이의 관계가 타당하다.",
            "판단이 배치안에 반영된 내용을 명확히 설명하며, 기대 효과와 실제 확인된 결과를 혼동하지 않는다."
          ]
        },
        "acceptable": {
          "criteria": [
            "설비 위치를 정한 근거와 배치안의 내용을 일부 설명한다.",
            "공정 흐름이나 생산 조건을 고려한 점은 드러나지만, 실제 조건과 선택한 위치의 연결이 충분히 구체적이지 않다."
          ]
        },
        "poor": {
          "criteria": [
            "설비 위치를 정한 근거 없이 배치안을 작성했다는 사실만 반복한다.",
            "효율적인 배치라는 일반적인 표현에 머물러 실제 작업 조건과의 관계를 확인할 수 없다.",
            "설비 구매 결정 등 질문과 다른 업무만 설명하여 본인의 배치 판단을 확인할 수 없다."
          ]
        }
      }
    },
    {
      "categoryId": "P14-C1",
      "itemId": "P14-C1-I2",
      "interviewBlueprint": {
        "questionIntent": "현장 작업자가 실행할 수 있는 작업 표준서 작성 행동을 검증한다. 시생산에서 확인한 조립 문제를 실제로 따를 수 있는 작업 지시로 표현한 내용 하나에 초점을 둔다.",
        "questionType": "behavioral",
        "expectedSTAR": {
          "situation": "신규 차종 도어 트림 조립 라인의 시생산 2회에서 나온 조립 문제를 작업 표준서 초판에 반영하던 상황이다.",
          "task": "담당한 표준서 작성 범위에서 작업자가 조립 작업을 그대로 수행할 수 있는 지시를 작성해야 했다.",
          "action": "표준서에 적은 작업 지시 한 가지를 실제 문구 또는 그에 준하는 구체적인 내용으로 설명한다.",
          "result": "작성한 지시에서 작업자가 해야 할 행동이 명확해진 부분을 설명한다. 현장 적용 결과는 확인된 경우에만 덧붙이며 필수로 요구하지 않는다."
        },
        "expectedEvidence": [
          "작업 표준서 초판에 실제로 작성한 작업 지시 한 가지의 구체적인 내용",
          "해당 지시가 필요했던 시생산 조립 문제 또는 작업상의 혼선",
          "그 지시만으로 작업자가 수행할 행동을 알아볼 수 있도록 표현한 작업 대상과 실행 내용"
        ]
      },
      "question": "신규 차종 도어 트림 조립 라인 양산 준비에서 시생산 2회를 반영해 작업 표준서 초판을 작성하셨던데요, 작업자가 그대로 따라 하도록 적은 작업 지시 한 가지는 어떤 내용이었어요?",
      "answerTip": "기억나는 사례 하나에 집중해 말씀해 주세요.",
      "evaluationRubric": {
        "excellent": {
          "criteria": [
            "실제로 작성한 작업 지시 한 가지를 문구나 그에 준하는 수준으로 구체적으로 제시한다.",
            "지시가 필요했던 조립 문제와 작성한 내용의 연결이 명확하다.",
            "작업 대상과 실행할 행동이 분명하여 작업자가 추측에 의존하지 않고 지시를 따를 수 있다."
          ]
        },
        "acceptable": {
          "criteria": [
            "실제로 작성한 작업 지시의 핵심 내용과 작성 배경을 일부 제시한다.",
            "작업자가 해야 할 행동은 파악되지만 대상이나 실행 표현이 모호해 추가 설명이 필요하다."
          ]
        },
        "poor": {
          "criteria": [
            "표준서에 문제를 반영했다는 설명만 있고 실제 작업 지시의 내용을 제시하지 못한다.",
            "주의해서 조립한다는 식의 추상적 표현에 머물러 작업자가 수행할 행동을 알 수 없다.",
            "표준서의 목차나 작성 절차만 설명하여 현장에서 실행할 수 있는 지시를 작성했는지 확인할 수 없다."
          ]
        }
      }
    }
  ]
}
